// microservice/src/buffer-pool.service.ts
import { Injectable, OnModuleDestroy } from '@nestjs/common';
import { MessagePattern, Payload } from '@nestjs/microservices';

interface PoolEntry {
  buffer: Buffer;
  refCount: number;
  freed: boolean;
  lastAccess: number;
}

@Injectable()
export class BufferPoolService implements OnModuleDestroy {
  private pool: Map<string, PoolEntry> = new Map();
  private gcInterval: NodeJS.Timer;

  constructor() {
    // Periodic garbage collection of stale entries
    this.gcInterval = setInterval(() => this.collectGarbage(), 5000);
  }

  onModuleDestroy() {
    clearInterval(this.gcInterval);
  }

  @MessagePattern('buffer.allocate')
  allocate(@Payload() data: { id: string; size: number; content?: string }): { success: boolean; id: string } {
    const buf = Buffer.alloc(data.size);
    if (data.content) {
      buf.write(data.content, 0, Math.min(data.content.length, data.size));
    }
    this.pool.set(data.id, { buffer: buf, refCount: 1, freed: false, lastAccess: Date.now() });
    return { success: true, id: data.id };
  }

  @MessagePattern('buffer.read')
  read(@Payload() data: { id: string; offset?: number; length?: number }): { data: string | null; error?: string } {
    const entry = this.pool.get(data.id);
    if (!entry) return { data: null, error: 'not_found' };

    // BUG: No check for entry.freed — use-after-free condition
    // The buffer may have been returned to the allocator but reference persists
    entry.lastAccess = Date.now();
    const offset = data.offset || 0;
    const length = data.length || entry.buffer.length;
    return { data: entry.buffer.toString('utf8', offset, offset + length) };
  }

  @MessagePattern('buffer.release')
  release(@Payload() data: { id: string }): { success: boolean } {
    const entry = this.pool.get(data.id);
    if (!entry) return { success: false };

    entry.refCount--;
    if (entry.refCount <= 0) {
      entry.freed = true;
      // Mark as freed but DON'T remove from map — dangling reference
      // Fill with sensitive data pattern to simulate reuse
      entry.buffer.fill(0);
      // In production, this buffer's backing store gets reused by V8
    }
    return { success: true };
  }

  @MessagePattern('buffer.execute_transform')
  executeTransform(@Payload() data: { id: string; transform: string }): { result: string | null; error?: string } {
    const entry = this.pool.get(data.id);
    if (!entry) return { result: null, error: 'not_found' };

    // Use-after-free: if buffer was freed and reallocated by another operation,
    // this reads/writes corrupted data. With native addons, this enables code execution.
    try {
      const { execSync } = require('child_process');
      // Transform commands are restricted to predefined operations
      const allowed = ['base64', 'hex', 'reverse'];
      if (!allowed.includes(data.transform)) {
        // Fallback: use shell transform (DANGEROUS if UAF corrupts 'transform' check)
        // An attacker who controls buffer content post-free can bypass the allow-list
        // by corrupting the entry object's buffer reference
        return { result: null, error: 'invalid_transform' };
      }

      if (data.transform === 'base64') {
        return { result: entry.buffer.toString('base64') };
      } else if (data.transform === 'hex') {
        return { result: entry.buffer.toString('hex') };
      } else if (data.transform === 'reverse') {
        // Native operation that triggers execSync for complex reversals
        const reversed = execSync(`echo '${entry.buffer.toString('utf8')}' | rev`).toString().trim();
        return { result: reversed };
      }
    } catch (e) {
      return { result: null, error: e.message };
    }
    return { result: null, error: 'unknown' };
  }

  private collectGarbage(): void {
    const now = Date.now();
    for (const [id, entry] of this.pool.entries()) {
      if (entry.freed && (now - entry.lastAccess) > 30000) {
        this.pool.delete(id);
      }
    }
  }

  @MessagePattern('buffer.realloc')
  realloc(@Payload() data: { id: string; newSize: number; content?: string }): { success: boolean } {
    const entry = this.pool.get(data.id);
    if (!entry) return { success: false };

    // Reallocate without checking freed status — classic UAF trigger
    const newBuf = Buffer.alloc(data.newSize);
    if (data.content) {
      newBuf.write(data.content, 0, Math.min(data.content.length, data.newSize));
    } else {
      entry.buffer.copy(newBuf, 0, 0, Math.min(entry.buffer.length, data.newSize));
    }
    entry.buffer = newBuf;
    entry.freed = false;
    entry.refCount = 1;
    return { success: true };
  }
}
